package com.lore.zzal.generation.client;
import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import java.net.http.HttpClient;import java.time.Duration;import java.util.*;
class OpenAiTextUsageRecorderTest {
 @Test void recordsOnlyUsageAndIdsWithoutBodyOrHeaders()throws Exception{try(var stub=new UsageStub()){var events=new ArrayList<ProviderUsageRecorder.Observation>();var c=new OpenAiTextClient(null,"SECRET_KEY",64,HttpClient.newHttpClient(),stub.endpoint(),Duration.ofSeconds(2),events::add);c.generate("SECRET_PROMPT",List.of(),ModelSpec.of("gpt-5"));assertThat(events).hasSize(2);var e=events.getLast();assertThat(e.xRequestId()).isEqualTo("req-test-1");assertThat(e.responseId()).isEqualTo("response-test-1");assertThat(e.usageRaw().path("completion_tokens_details").path("reasoning_tokens").asInt()).isEqualTo(5);String serialized=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(events);assertThat(serialized).doesNotContain("SECRET_KEY","SECRET_PROMPT","SECRET_RESPONSE_TEXT","SECRET_HEADER","b64_json");assertThat(stub.requests.get()).isEqualTo(1);}}
 @Test void parseFailureRetainsHeaderUnknown()throws Exception{try(var stub=new UsageStub()){stub.body="not-json";var events=new ArrayList<ProviderUsageRecorder.Observation>();var c=new OpenAiTextClient(null,"TEST",64,HttpClient.newHttpClient(),stub.endpoint(),Duration.ofSeconds(2),events::add);assertThatThrownBy(()->c.generate("p",List.of(),ModelSpec.of("gpt-5"))).isInstanceOf(Exception.class);assertThat(events).hasSize(1);assertThat(events.getFirst().outcome()).isEqualTo(ProviderUsageRecorder.Outcome.UNKNOWN);assertThat(events.getFirst().httpStatus()).isEqualTo(200);assertThat(events.getFirst().xRequestId()).isEqualTo("req-test-1");}}
 @Test void timeoutUnknownAndNoRetry()throws Exception{try(var stub=new UsageStub()){stub.delay=1500;var events=new ArrayList<ProviderUsageRecorder.Observation>();var c=new OpenAiTextClient(null,"TEST",64,HttpClient.newHttpClient(),stub.endpoint(),Duration.ofMillis(500),events::add);assertThatThrownBy(()->c.generate("p",List.of(),ModelSpec.of("gpt-5"))).isInstanceOf(java.net.http.HttpTimeoutException.class);assertThat(events.getFirst().httpStatus()).isZero();assertThat(events.getFirst().xRequestId()).isNull();Thread.sleep(1600);assertThat(stub.requests.get()).isEqualTo(1);}}
 @Test void recorderFailureStopsCurrentCall()throws Exception{try(var stub=new UsageStub()){var c=new OpenAiTextClient(null,"TEST",64,HttpClient.newHttpClient(),stub.endpoint(),Duration.ofSeconds(2),e->{throw new java.io.IOException("record failed");});assertThatThrownBy(()->c.generate("p",List.of(),ModelSpec.of("gpt-5"))).isInstanceOf(java.io.IOException.class);assertThat(stub.requests.get()).isEqualTo(1);}}
 @Test void absentIdsAndNonNumericUsageAreNotInvented()throws Exception{try(var stub=new UsageStub()){stub.requestId=false;stub.body="{\"choices\":[{\"message\":{\"content\":\"ok\"}}],\"usage\":{\"unexpected\":\"SECRET_TEXT\"}}";var events=new ArrayList<ProviderUsageRecorder.Observation>();var c=new OpenAiTextClient(null,"TEST",64,HttpClient.newHttpClient(),stub.endpoint(),Duration.ofSeconds(2),events::add);c.generate("p",List.of(),ModelSpec.of("gpt-5"));assertThat(events.getLast().usageRaw()).isNull();assertThat(events.getLast().responseId()).isNull();assertThat(events.getLast().xRequestId()).isNull();assertThat(events.getLast().outcome()).isEqualTo(ProviderUsageRecorder.Outcome.UNKNOWN);}}
}
